using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

[TestClass]
public class ChatEvals
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("AZURE_OPENAI_ENDPOINT is not set.");
        var deploymentName = Environment.GetEnvironmentVariable("AZURE_OPENAI_DEPLOYMENT") ?? "gpt-4o-mini";

        var chatClient = new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new Azure.Identity.DefaultAzureCredential())
            .GetChatClient(deploymentName)
            .AsIChatClient();

        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-results"),
            chatConfiguration: new ChatConfiguration(chatClient),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
                new GroundednessEvaluator(),
            ]);
    }

    [TestMethod]
    public async Task Greeting_IsCoherentAndRelevant()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync();

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertAllMetricsPassMinimumScore(scenario, 3);
    }

    [TestMethod]
    public async Task Factual_Question_IsGroundedAndFluent()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync();

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant that provides concise factual answers."),
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertAllMetricsPassMinimumScore(scenario, 3);
    }

    [TestMethod]
    public async Task MultiTurn_Conversation_MaintainsCoherence()
    {
        await using var scenario = await s_reportingConfiguration!.CreateScenarioRunAsync();

        var chatClient = scenario.ChatConfiguration!.ChatClient;

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I'd like to plan a trip to Japan.")
        };

        var response1 = await chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What are the best months to visit?"));
        var response2 = await chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);

        EvaluationAssertions.AssertAllMetricsPassMinimumScore(scenario, 3);
    }
}

internal static class EvaluationAssertions
{
    public static void AssertAllMetricsPassMinimumScore(ScenarioRun scenario, int minimumScore)
    {
        foreach (var result in scenario.AllEvaluationResults)
        {
            foreach (var metric in result.Metrics.Values)
            {
                if (metric is NumericMetric numericMetric)
                {
                    Assert.IsTrue(
                        numericMetric.Value >= minimumScore,
                        $"Metric '{metric.Name}' scored {numericMetric.Value}, below minimum {minimumScore}.");
                }
            }
        }
    }
}

